import{_ as o,l as i,o as e,c as s,v as t,p as n,x as r,d as m,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Watermark 与乱序","description":"","frontmatter":{"title":"Watermark 与乱序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/watermark-late-events.md","filePath":"cs/watermark-late-events.md","lastUpdated":1789023840000}'),c={name:"cs/watermark-late-events.md"};function h(k,a,_,u,E,w){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="watermark-与乱序" tabindex="-1">Watermark 与乱序 <a class="header-anchor" href="#watermark-与乱序" aria-label="Permalink to &quot;Watermark 与乱序&quot;">​</a></h1><div class="epigraph"><p>事件时间窗口要关，必须有一条「不会再有更早事件」的声明。watermark 是这条声明；它错了，结果就永久偏或状态永不释放。</p><footer>—— 据 Akidau et al., VLDB 2015；乱序流与迟到处理通识</footer></div><p><a href="/cs/stream-windows">上一课</a>切开窗口。缺口是<strong>乱序</strong>：网络与分区让事件时间 \\(t\\) 的记录在 \\(t+\\Delta\\) 才到。本课钉 watermark；恰好一次下一课谈投递语义，不在这里重讲窗口种类。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>启发式 watermark（事件时间的分位数、或「处理时间减去 bound」）过快关窗会丢迟到；过慢则状态膨胀、延迟变大。允许迟到：关窗后的修订（retraction）或侧输出。缺口是把迟到当成一等错误，而不是「调大窗口」。</p><p><span class="marginnote">乱序不是 bug，是分区网络的常态。与分布式课的故障模型：迟到像漏发后的补包，不是崩溃。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生成：每源或每分区一条单调不减的 watermark，聚合取 min。触发器：on-time 一次，allowed lateness 内再更新。监控：迟到率、关窗延迟、状态字节。与表格式：修订写成 changelog。</p>',8)),(e(),n(p,null,{default:r(()=>[d(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20W%5B%22watermark%22%5D%0A%20%20W%20--%3E%20CLOSE%5B%22%E5%85%B3%E7%AA%97%22%5D%0A%20%20LATE%5B%22%E8%BF%9F%E5%88%B0%22%5D%20--%3E%20REV%5B%22%E4%BF%AE%E8%AE%A2%20%2F%20%E4%BE%A7%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>watermark \\(w\\) 断言：事件时间 \\(\\lt w\\) 的记录不再进入主输出。这是安全性（不再改）与活性（窗能关）的折中。多源取 min，最慢分区拖住全局——像最小快照挡 GC。空闲源要空闲 watermark，否则窗永不关。检查点必须含 \\(w\\) 与窗口状态，否则恢复会重复关窗或永不关。</p><p>迟到策略：丢弃、侧输出、或撤回旧合计再发新值。后者要求下游能撤，接到恰好一次与幂等。乱序缓冲在关窗前按事件时间排一小段，像微型外部排序。启发式过快丢数据，过慢堆状态与延迟。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证某启发式最优。下一课 exactly-once 假定窗已经能关。不要用处理时间 watermark 冒充事件时间正确。TrueTime 的 \\(\\epsilon\\) 是另一套时钟不确定度，不要混名。</p><p>后课默认：事件时间窗口必有 watermark 与迟到合同。watermark 是流的进度钟，不是墙钟。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>watermark 是关事件时间窗口的声明，会错。</li><li>迟到要有修订或侧输出合同；min 进度会被慢源拖住。</li><li>恰好一次下一课。</li><li>出处：Akidau et al., VLDB 2015。</li></ul>',8))])}const f=o(c,[["render",h]]);export{A as __pageData,f as default};
